  --border-strong: #323849;
  --text: #e7eaf2;
  --text-muted: #9aa3b8;
  --text-dim: #6b7388;
  --accent: #7c9cff;
  --danger: #ef4d5e;
  --danger-hover: #ff6273;
  --danger-soft: rgba(239, 77, 94, 0.12);
  --shadow-lg: 0 30px 80px rgba(0, 0, 0, 0.55), 0 8px 24px rgba(0, 0, 0, 0.35);
  --radius: 14px;
  --radius-sm: 10px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: radial-gradient(1200px 700px at 80% -10%, #1a1f30 0%, transparent 60%),
              radial-gradient(900px 600px at -10% 110%, #16202b 0%, transparent 55%),
              var(--bg-0);
  color: var(--text);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* Top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.7);
  backdrop-filter: blur(8px);
  position: sticky;
  top: 0;
  z-index: 10;
}
.brand { display: flex; align-items: center; gap: 10px; font-weight: 600; letter-spacing: 0.2px; }
.logo-dot {
  width: 12px; height: 12px; border-radius: 50%;
  background: linear-gradient(135deg, #7c9cff, #b66bff);
  box-shadow: 0 0 14px rgba(124, 156, 255, 0.55);
}
.brand-name { color: var(--text); }
.topnav { display: flex; gap: 6px; }
.nav-link {
  color: var(--text-muted);
  text-decoration: none;
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 14px;
  transition: color .15s ease, background .15s ease;
}
.nav-link:hover { color: var(--text); background: var(--bg-2); }
.nav-link.active { color: var(--text); background: var(--bg-3); }

/* Preview */
.preview {
  display: flex;
  justify-content: center;
  padding: 48px 24px 80px;
}
.image-card {
  margin: 0;
  width: 100%;
  max-width: 880px;
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.45);
}
.image-frame {
  background: #000;
  aspect-ratio: 4 / 3;
  overflow: hidden;
}
.image-frame img {
  width: 100%; height: 100%; object-fit: cover; display: block;
}
.meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 22px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
}
.title { margin: 0 0 4px; font-size: 18px; font-weight: 600; }
.sub { margin: 0; color: var(--text-muted); font-size: 13px; display: flex; gap: 8px; flex-wrap: wrap; }
.dot-sep { color: var(--text-dim); }
.actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 14px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  font: inherit;
  font-weight: 500;
  font-size: 14px;
  cursor: pointer;
  color: var(--text);
  background: transparent;
  transition: background .15s ease, border-color .15s ease, color .15s ease, transform .05s ease;
  user-select: none;
}
.btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.btn:active { transform: translateY(1px); }
.btn svg { display: block; }

.btn-ghost {
  background: var(--bg-2);
  border-color: var(--border);
  color: var(--text);
}
.btn-ghost:hover { background: var(--bg-3); border-color: var(--border-strong); }

.btn-secondary {
  background: var(--bg-2);
  border-color: var(--border);
  color: var(--text);
}
.btn-secondary:hover { background: var(--bg-3); border-color: var(--border-strong); }

.btn-danger {
  background: var(--danger);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 6px 18px rgba(239, 77, 94, 0.25);
}
.btn-danger:hover { background: var(--danger-hover); }

/* Modal */
.modal[hidden] { display: none; }
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
}
.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(5, 7, 11, 0.65);
  backdrop-filter: blur(6px);
  animation: fade-in .18s ease-out;
}
.modal-panel {
  position: relative;
  width: 100%;
  max-width: 440px;
  background: linear-gradient(180deg, #1a1f2b 0%, #151823 100%);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  padding: 28px 26px 22px;
  box-shadow: var(--shadow-lg);
  animation: pop-in .2s cubic-bezier(.2,.8,.25,1);
}
.modal-close {
  position: absolute;
  top: 12px; right: 12px;
  width: 32px; height: 32px;
  display: grid; place-items: center;
  border-radius: 8px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: background .15s ease, color .15s ease;
}
.modal-close:hover { background: var(--bg-3); color: var(--text); }
.modal-close:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.modal-icon {
  width: 48px; height: 48px;
  border-radius: 12px;
  display: grid; place-items: center;
  background: var(--danger-soft);
  color: var(--danger);
  margin-bottom: 14px;
  border: 1px solid rgba(239, 77, 94, 0.25);
}
.modal-title {
  margin: 0 0 8px;
  font-size: 18px;
  font-weight: 600;
  color: var(--text);
}
.modal-desc {
  margin: 0 0 22px;
  color: var(--text-muted);
  font-size: 14px;
}
.modal-desc strong { color: var(--text); font-weight: 600; }
.modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

/* Toast */
.toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%) translateY(10px);
  background: var(--bg-3);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 10px 16px;
  border-radius: 999px;
  font-size: 14px;
  box-shadow: 0 12px 30px rgba(0,0,0,0.4);
  opacity: 0;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 200;
}
.toast[hidden] { display: none; }
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop-in {
  from { opacity: 0; transform: translateY(8px) scale(.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 520px) {
  .topbar { padding: 14px 18px; }
  .topnav { display: none; }
  .preview { padding: 24px 14px 60px; }
  .meta { flex-direction: column; align-items: flex-start; }
  .actions { width: 100%; }
  .modal-actions { flex-direction: column-reverse; }
  .modal-actions .btn { width: 100%; justify-content: center; }
}
