  const trigger = document.getElementById('deleteTrigger');
  const dialog = document.getElementById('deleteDialog');
  const confirmBtn = document.getElementById('confirmDelete');
  const toast = document.getElementById('toast');
  const card = document.querySelector('.image-card');

  let lastFocused = null;

  const focusableSelector =
    'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

  function openDialog() {
    if (!dialog.hasAttribute('hidden')) return;
    lastFocused = document.activeElement;
    dialog.removeAttribute('hidden');
    document.body.style.overflow = 'hidden';
    const focusables = dialog.querySelectorAll(focusableSelector);
    const cancelBtn = dialog.querySelector('.btn-secondary');
    (cancelBtn || focusables[0]).focus();
  }

  function closeDialog() {
    if (dialog.hasAttribute('hidden')) return;
    dialog.setAttribute('hidden', '');
    document.body.style.overflow = '';
    if (lastFocused && document.contains(lastFocused)) {
      lastFocused.focus();
    }
  }

  function showToast(msg) {
    toast.textContent = msg;
    toast.removeAttribute('hidden');
    requestAnimationFrame(() => toast.classList.add('show'));
    setTimeout(() => {
      toast.classList.remove('show');
      setTimeout(() => toast.setAttribute('hidden', ''), 250);
    }, 2200);
  }

  function trapFocus(e) {
    if (e.key !== 'Tab' || dialog.hasAttribute('hidden')) return;
    const focusables = Array.from(dialog.querySelectorAll(focusableSelector))
      .filter(el => !el.hasAttribute('disabled'));
    if (!focusables.length) return;
    const first = focusables[0];
    const last = focusables[focusables.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }

  trigger.addEventListener('click', openDialog);

  dialog.addEventListener('click', (e) => {
    if (e.target.matches('[data-close]')) closeDialog();
  });

  document.addEventListener('keydown', (e) => {
    if (dialog.hasAttribute('hidden')) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeDialog();
    } else {
      trapFocus(e);
    }
  });

  confirmBtn.addEventListener('click', () => {
    closeDialog();
    if (card) {
      card.style.transition = 'opacity .25s ease, transform .25s ease';
      card.style.opacity = '0';
      card.style.transform = 'scale(.98)';
      setTimeout(() => { card.style.display = 'none'; }, 260);
    }
    showToast('Image deleted');
  });
})();
